# Example of a C++ Class Definition with OOP Principles

#include <iostream>
using namespace std;

// Base class for inheritance
class Shape {
public:
    virtual void draw() const = 0; // Pure virtual function for polymorphism
    virtual ~Shape() {}
};

// Derived class with virtual inheritance
class Circle : public virtual Shape {
public:
    Circle(double r) : radius(r) {}
    void draw() const override {
        cout << "Drawing a circle with radius: " << radius << endl;
    }
    double radius;
};

// Another derived class with virtual inheritance
class Square : public virtual Shape {
public:
    Square(double s) : side(s) {}
    void draw() const override {
        cout << "Drawing a square with side: " << side << endl;
    }
    double side;
};

// Class with aggregation
class Drawing {
public:
    Drawing() : shape(nullptr) {}
    ~Drawing() {
        if (shape) delete shape;
    }
    void addShape(Shape* s) {
        shape = s;
    }
    void draw() {
        if (shape) shape->draw();
    }
private:
    Shape* shape;
};

// Class with composition
class CompositeShape {
public:
    CompositeShape() {}
    ~CompositeShape() {
        for (auto& s : shapes) delete s;
    }
    void add(Shape* s) {
        shapes.push_back(s);
    }
    void draw() {
        for (auto& s : shapes) s->draw();
    }
private:
    vector<Shape*> shapes;
};

// Main function to demonstrate usage
int main() {
    // Example of virtual inheritance
    Circle c(5);
    Square s(10);
    c.draw(); // Output: Drawing a circle with radius: 5
    s.draw(); // Output: Drawing a square with side: 10

    // Example of aggregation
    Drawing d;
    d.addShape(&c);
    d.draw(); // Output: Drawing a circle with radius: 5

    // Example of composition
    CompositeShape comp;
    comp.add(&c);
    comp.add(&s);
    comp.draw(); // Output: Drawing a circle with radius: 5
    //                     Drawing a square with side: 10

    return 0;
}

